begin;
create extension if not exists pgtap with schema extensions;
select plan(40);
insert into public.entries(id,owner_id,title,body,date_precision,occurred_label) values
('94000000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000001','History original','Original writing','year','University year'),
('94000000-0000-4000-8000-000000000002','10000000-0000-0000-0000-000000000001','Linked context','Another memory','unknown',null);
insert into public.tags(id,owner_id,name) values('94200000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000001','history-tag');
insert into public.locations(id,owner_id,name) values
('94400000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000001','Old location name'),
('94400000-0000-4000-8000-000000000002','10000000-0000-0000-0000-000000000001','Home location');
insert into public.timeline_tracks(id,owner_id,name) values('94500000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000001','History track');
insert into public.entry_tags values('94000000-0000-4000-8000-000000000001','94200000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000001',now());
insert into public.entry_places(entry_id,place_id,owner_id) values('94000000-0000-4000-8000-000000000001','94400000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000001');
insert into public.timeline_items(entry_id,track_id,owner_id,timeline_kind) values('94000000-0000-4000-8000-000000000001','94500000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000001','event');
insert into public.entry_links(source_entry_id,target_entry_id,owner_id) values('94000000-0000-4000-8000-000000000001','94000000-0000-4000-8000-000000000002','10000000-0000-0000-0000-000000000001');
update public.entries set title='History revised',body='Current writing',date_precision='unknown',occurred_label=null where id='94000000-0000-4000-8000-000000000001';
delete from public.entry_tags where entry_id='94000000-0000-4000-8000-000000000001';
delete from public.entry_places where entry_id='94000000-0000-4000-8000-000000000001';
delete from public.timeline_items where entry_id='94000000-0000-4000-8000-000000000001';
delete from public.entry_links where source_entry_id='94000000-0000-4000-8000-000000000001';
update public.locations set name='Current shared name' where id='94400000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select is(public.entry_history('94000000-0000-4000-8000-000000000001')->>'total_count','1','Earlier version is browsable');
select is(public.entry_history('94000000-0000-4000-8000-000000000001')->'versions'->0->'snapshot'->>'history_schema','3','New snapshots carry the canonical schema marker');
select is(public.entry_history('94000000-0000-4000-8000-000000000001')->'versions'->0->'snapshot'->'tags'->0->>'name','history-tag','Snapshot records original tag name');
select is((select count(*) from public.entry_history_index('History revised')),1::bigint,'History index finds current writing');
select is(public.restore_entry_version('94000000-0000-4000-8000-000000000001',1,2),3,'Restore creates next revision');
select is((select body from public.entries where id='94000000-0000-4000-8000-000000000001'),'Original writing','Restores writing');
select is((select date_precision from public.entries where id='94000000-0000-4000-8000-000000000001'),'year','Restores imprecise date');
select is((select count(*) from public.entry_tags where entry_id='94000000-0000-4000-8000-000000000001'),1::bigint,'Restores tag links');
select is((select count(*) from public.entry_places where entry_id='94000000-0000-4000-8000-000000000001'),1::bigint,'Restores Place links');
select is((select count(*) from public.timeline_items where entry_id='94000000-0000-4000-8000-000000000001'),1::bigint,'Restores Timeline placement');
select is((select count(*) from public.entry_links where source_entry_id='94000000-0000-4000-8000-000000000001'),1::bigint,'Restores Entry links');
select is((select name from public.locations where id='94400000-0000-4000-8000-000000000001'),'Location not set','Location label remains derived rather than user-authored');
select is((select snapshot->>'body' from public.entry_versions where entry_id='94000000-0000-4000-8000-000000000001' and version=2),'Current writing','Pre-restore current version remains available');
select is(public.restore_entry_version('94000000-0000-4000-8000-000000000001',1,2),null::integer,'Stale restore rejected');
select is(public.restore_entry_version('94000000-0000-4000-8000-000000000001',2,3),4,'Restoration can itself be undone');
select is((select count(*) from public.entry_tags where entry_id='94000000-0000-4000-8000-000000000001'),0::bigint,'Recorded empty links are restored precisely');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000099',true);
select is(public.entry_history('94000000-0000-4000-8000-000000000001'),null::jsonb,'Other owner cannot inspect history');
select is(public.restore_entry_version('94000000-0000-4000-8000-000000000001',1,4),null::integer,'Other owner cannot restore history');
reset role;
delete from public.locations where id='94400000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select throws_ok($$select public.restore_entry_version('94000000-0000-4000-8000-000000000001',1,4)$$,'P0001','history_reference_unavailable','Missing historical reference blocks whole restore');
select is((select revision from public.entries where id='94000000-0000-4000-8000-000000000001'),4,'Failed restore does not create partial revision');
update public.entries set deleted_at=now() where id='94000000-0000-4000-8000-000000000001';
select is(public.restore_entry_version('94000000-0000-4000-8000-000000000001',2,5),null::integer,'Trash must be restored first');
select throws_ok($$select public.entry_history('94000000-0000-4000-8000-000000000001',21,0)$$,'22023','invalid_history_page','History page bounds enforced');
reset role;
-- Specialized facts travel with Entry restoration, not as independent partial writes.
insert into public.entries(id,owner_id,title,item_kind,item_subtype) values
('94600000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000001','Goal v1','goal','goal'),
('94600000-0000-4000-8000-000000000002','10000000-0000-0000-0000-000000000001','Home v1','entity','home'),
('94600000-0000-4000-8000-000000000003','10000000-0000-0000-0000-000000000001','Vehicle v1','entity','vehicle');
insert into public.goals(entry_id,owner_id,status) values('94600000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000001','active');
insert into public.homes(entry_id,owner_id,place_id,move_in_reason) values('94600000-0000-4000-8000-000000000002','10000000-0000-0000-0000-000000000001','94400000-0000-4000-8000-000000000002','Study');
insert into public.vehicles(entry_id,owner_id,model,color) values('94600000-0000-4000-8000-000000000003','10000000-0000-0000-0000-000000000001','Original model','Blue');
update public.entries set title=title||' changed' where id in ('94600000-0000-4000-8000-000000000001','94600000-0000-4000-8000-000000000002','94600000-0000-4000-8000-000000000003');
update public.goals set status='let_go' where entry_id='94600000-0000-4000-8000-000000000001';
update public.homes set move_in_reason='Work' where entry_id='94600000-0000-4000-8000-000000000002';
update public.vehicles set color='Red' where entry_id='94600000-0000-4000-8000-000000000003';
set local role authenticated;
select is(public.restore_entry_version('94600000-0000-4000-8000-000000000001',1,2),3,'Restores Goal atomically');
select is((select status from public.goals where entry_id='94600000-0000-4000-8000-000000000001'),'active','Restores Goal status');
select is(public.restore_entry_version('94600000-0000-4000-8000-000000000002',1,2),3,'Restores Home atomically');
select is((select move_in_reason from public.homes where entry_id='94600000-0000-4000-8000-000000000002'),'Study','Restores Home details');
select is(public.restore_entry_version('94600000-0000-4000-8000-000000000003',1,2),3,'Restores Vehicle atomically');
select is((select color from public.vehicles where entry_id='94600000-0000-4000-8000-000000000003'),'Blue','Restores Vehicle details');
reset role;
-- Snapshots outside the canonical contract are rejected without partial writes.
update public.entries set body='Legacy previous' where id='94000000-0000-4000-8000-000000000002';
update public.entry_versions set snapshot=snapshot-array['tags','places','timeline_items','timeline','links','related_entry_ids','attachments','history_schema'] where entry_id='94000000-0000-4000-8000-000000000002';
insert into public.entry_tags values('94000000-0000-4000-8000-000000000002','94200000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000001',now());
set local role authenticated;
select throws_ok($$select public.restore_entry_version('94000000-0000-4000-8000-000000000002',1,2)$$,'P0001','history_schema_unsupported','Noncanonical history cannot be restored');
select is((select revision from public.entries where id='94000000-0000-4000-8000-000000000002'),2,'Rejected history leaves the revision unchanged');
select is((select count(*) from public.entry_tags where entry_id='94000000-0000-4000-8000-000000000002'),1::bigint,'Rejected history leaves current relationships unchanged');
reset role;
select ok(not has_function_privilege('anon','public.restore_entry_version(uuid,integer,integer)','execute'),'Anonymous restoration denied');
select ok(not has_function_privilege('authenticated','public.entry_history_snapshot(public.entries)','execute'),'Internal snapshot helper not exposed to clients');
select ok(not has_table_privilege('authenticated','public.entry_versions','update'),'History remains immutable to clients');
insert into public.entries(id,owner_id,title) values('94700000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000001','Photo history');
insert into storage.objects(bucket_id,name) values('entry-media','history-test-original.png');
insert into public.attachments(id,owner_id,entry_id,object_path,mime_type,byte_size) values('94800000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000001','94700000-0000-4000-8000-000000000001','history-test-original.png','image/png',10);
update public.entries set body='Edited photo note' where id='94700000-0000-4000-8000-000000000001';
update public.attachments set deleted_at=now() where id='94800000-0000-4000-8000-000000000001';
set local role authenticated;
select is(public.restore_entry_version('94700000-0000-4000-8000-000000000001',1,2),3,'Photo membership restoration succeeds');
select is((select deleted_at from public.attachments where id='94800000-0000-4000-8000-000000000001'),null::timestamptz,'Historical photo returns from soft removal');
select is(public.restore_entry_version('94700000-0000-4000-8000-000000000001',2,3),4,'Empty photo membership can be restored');
select ok((select deleted_at is not null from public.attachments where id='94800000-0000-4000-8000-000000000001'),'Newer photo is soft removed, not deleted');
reset role;
update storage.objects set name='history-test-missing-original.png' where bucket_id='entry-media' and name='history-test-original.png';
set local role authenticated;
select throws_ok($$select public.restore_entry_version('94700000-0000-4000-8000-000000000001',1,4)$$,'P0001','history_attachment_unavailable','Missing original blocks the entire restore');
select is((select revision from public.entries where id='94700000-0000-4000-8000-000000000001'),4,'Missing original leaves current revision unchanged');
reset role;
select * from finish();
rollback;
